import abc
import functools
import inspect
import typing

from jsilib import _utils

__all__ = ['AbstractAsyncContextManager', 'asynccontextmanager']


if _utils.python_version_gt(3, 6):

    from contextlib import AbstractAsyncContextManager, asynccontextmanager

else:  # Py36

    class AbstractAsyncContextManager(abc.ABC):

        async def __aenter__(self):
            return self

        @abc.abstractmethod
        async def __aexit__(self, exc_type: typing.Type[Exception], exc_value: Exception, traceback: typing.Any):
            return None

    class _GeneratorBasedContextManager(AbstractAsyncContextManager):

        def __init__(self, gen: typing.AsyncGenerator, *args, **kwargs):
            self._gen = gen
            self._args = args
            self._kwargs = kwargs

        async def __aenter__(self):
            self._iter = self._gen(*self._args, **self._kwargs)
            return await self._iter.__anext__()

        async def __aexit__(self, exc_type: typing.Type[Exception], exc_value: Exception, traceback: typing.Any):
            try:
                await self._iter.__anext__()
                raise RuntimeError(f"{self._gen.__name__!r} async generator has more than one yield statements")
            except StopAsyncIteration:
                pass

    def asynccontextmanager(func):
        if not inspect.isasyncgenfunction(func):
            raise TypeError(f"{func.__name__!r} object is not async generator function")

        @functools.wraps(func)
        def proxy(*args, **kwargs):
            return _GeneratorBasedContextManager(func, *args, **kwargs)

        return proxy
